                <div>
                    <p className="text-sm text-gray-600">You have selected:</p>
                    <p className="font-bold text-blue-800 text-lg">{firstSlot.type} &mdash; {firstSlot.day}, {firstSlot.date}</p>
                    <div className="text-sm font-medium text-gray-700 mt-1">
                        {selectedSlots.map((slot, idx) => (
                            <span key={idx} className="block">• {slot.time}</span>
                        ))}
                    </div>
                </div>
                <button onClick={onClearSelection} className="text-sm bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold py-2 px-4 rounded-lg transition-colors whitespace-nowrap">Change Slots</button>
            </div>

            <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8">
                    {renderInput("1. Name", "name", "text")}
                    {renderInput("2. PRN / Employee No.", "prn", "text")}
                    {renderInput("3. Contact No.", "contact", "tel")}
                    {renderInput("4. Requester E-Mail ID", "email", "email")}
                    <div className="mb-4">
                        <label htmlFor="supervisor" className="block text-sm font-medium text-gray-700 mb-1">5. Name of the supervisor/ PI/ Co-PI</label>
                        <select id="supervisor" name="supervisor" value={formData.supervisor} onChange={handleSupervisorChange} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500">
                            {SUPERVISORS.map(s => <option key={s.email} value={s.name}>{s.name}</option>)}
                        </select>
                    </div>
                </div>

                <div className="mb-4">
                    <h3 className="block text-sm font-medium text-gray-700 mb-1">6. Researcher (Tick any)</h3>
                    <div className="flex flex-wrap gap-4 mt-2">
                        {['BTech', 'MTech', 'PhD', 'JRF-SRF', 'Faculty', 'Consultant'].map(type => (
                            <label key={type} className="flex items-center space-x-2">
                                <input type="radio" name="researcherType" value={type} checked={formData.researcherType === type} onChange={handleChange} className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300"/>
                                <span>{type}</span>
                            </label>
                        ))}
                    </div>
                </div>

                {formData.researcherType === 'Consultant' && (
                    <div className="mb-6 p-5 bg-blue-50 border border-blue-200 rounded-lg animate-fade-in">
                        <h3 className="text-lg font-semibold text-blue-900 mb-3 border-b border-blue-200 pb-2">Consultancy Project Details</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-2">
                            {renderInput("Client Name", "consultantClientName", "text", true)}
                            {renderInput("Title of Project/Work", "consultantProjectTitle", "text", true)}
                            {renderInput("Amount Paid (INR)", "consultantAmountPaid", "number", true)}
                            <div className="grid grid-cols-2 gap-2">
                                {renderInput("Transaction No", "consultantTransactionNo", "text", true)}
                                {renderInput("Date", "consultantTransactionDate", "date", true)}
                            </div>
                        </div>
                        <p className="text-xs text-blue-600 -mt-2 italic">* Please attach payment proofs in email correspondence.</p>
                    </div>
                )}

                <div className="mb-4 border-t pt-4 mt-4">
                    <label htmlFor="workDescription" className="block text-sm font-medium text-gray-700 mb-1">7. Work Description (Not more than 50 words)</label>
                    <textarea id="workDescription" name="workDescription" value={formData.workDescription} onChange={handleChange} required rows={3} maxLength={300} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"></textarea>
                </div>

                <div className="mb-4">
                    <label htmlFor="equipment" className="block text-sm font-medium text-gray-700 mb-1">8. List of equipment, apparatus, and accessories to be used</label>
                    <textarea id="equipment" name="equipment" value={formData.equipment} onChange={handleChange} required rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"></textarea>
                </div>

                <div className="mb-4 border-t pt-4 mt-4">
                    <h3 className="block text-sm font-medium text-gray-700 mb-1">9. Any special conditions during the test?</h3>
                    <div className="flex gap-4 mt-2">
                        <label className="flex items-center space-x-2"><input type="radio" name="hasSpecialConditions" value="No" checked={formData.hasSpecialConditions === 'No'} onChange={handleChange}/><span>No</span></label>
                        <label className="flex items-center space-x-2"><input type="radio" name="hasSpecialConditions" value="Yes" checked={formData.hasSpecialConditions === 'Yes'} onChange={handleChange}/><span>Yes</span></label>
                    </div>
                    {formData.hasSpecialConditions === 'Yes' && (
                        <div className="mt-4 pl-4 border-l-2">
                            <p className="text-sm text-gray-600 mb-2">If yes, please mention:</p>
                             <div className="flex flex-wrap gap-x-4 gap-y-2 text-sm">
                                {['Thermal Variation', 'Acidic', 'Marine', 'Biohazard', 'Radioactive', 'Hazardous'].map(cond => (
                                    <label key={cond} className="flex items-center space-x-2"><input type="checkbox" value={cond} onChange={(e) => handleCheckboxChange(e, 'specialConditionTypes')} className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300 rounded"/><span>{cond}</span></label>
                                ))}
                            </div>
                            <input type="text" name="otherSpecialCondition" placeholder="Others (please specify)" value={formData.otherSpecialCondition} onChange={handleChange} className="mt-2 w-full md:w-1/2 px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"/>
                        </div>
                    )}
                </div>

                <div className="mb-6">
                    <label htmlFor="specialInstructions" className="block text-sm font-medium text-gray-700 mb-1">10. Any special instructions for Lab assistants or support staff?</label>
                    <textarea id="specialInstructions" name="specialInstructions" value={formData.specialInstructions} onChange={handleChange} rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"></textarea>
                </div>

                <div className="border-t pt-6">
                    <div className="mb-4 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                        <p className="text-sm text-yellow-800 font-semibold mb-2">Important Documentation Required:</p>
                        <div className="flex flex-col gap-2">
                            <button 
                                type="button" 
                                onClick={onViewSafety}
                                className={`text-left text-sm flex items-center gap-2 ${hasReadSafety ? 'text-green-600 font-bold' : 'text-blue-600 hover:underline'}`}
                            >
                                {hasReadSafety ? '✓' : '→'} Read Safety Instructions
                            </button>
                            <button 
                                type="button" 
                                onClick={onViewTerms}
                                className={`text-left text-sm flex items-center gap-2 ${hasReadTerms ? 'text-green-600 font-bold' : 'text-blue-600 hover:underline'}`}
                            >
                                {hasReadTerms ? '✓' : '→'} Read Terms and Conditions
                            </button>
                        </div>
                        {!canCheckTerms && (
                            <p className="text-[10px] text-yellow-600 mt-2 italic">* You must visit both pages above before you can accept the terms.</p>
                        )}
                    </div>

                    <div className="flex items-start mb-4">
                        <input 
                            id="terms" 
                            type="checkbox" 
                            required 
                            disabled={!canCheckTerms}
                            checked={acceptedPolicies}
                            onChange={(e) => setAcceptedPolicies(e.target.checked)}
                            className={`mt-1 h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded ${!canCheckTerms ? 'cursor-not-allowed opacity-50' : 'cursor-pointer'}`} 
                        />
                        <label htmlFor="terms" className={`ml-2 block text-sm ${!canCheckTerms ? 'text-gray-400' : 'text-gray-900 cursor-pointer'}`}>
                            I accept the Terms and Conditions and safety instructions. I have read and understood the required protocols for lab utilization.
                        </label>
                    </div>

                    <button 
                        type="submit" 
                        disabled={isSubmitting || !acceptedPolicies} 
                        className="w-full bg-blue-600 text-white font-bold py-3 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-gray-400"
                    >
                        {isSubmitting ? 'Submitting...' : 'Submit for Approval'}
                    </button>
                </div>
            </form>
        </div>
    );
};

export default Form;

import React, { useState, useCallback } from 'react';
import type { FormData, SelectedSlot } from './types';
import { ApprovalStatus } from './types';
import { LAB_INCHARGE, HOD, SUPERVISORS } from './constants';

import Header from './components/Header';
import CalendarView from './components/CalendarView';
import Form from './components/Form';
import ApprovalStatusDisplay from './components/ApprovalStatus';
import LandingPage from './components/LandingPage';
import ContactPage from './components/ContactPage';
import ExperimentsPage from './components/ExperimentsPage';
import ResearchPage from './components/ResearchPage';
import ConsultancyPage from './components/ConsultancyPage';
import SafetyPage from './components/SafetyPage';
import TermsPage from './components/TermsPage';
import EmailToast, { EmailData } from './components/EmailToast';

// Helper to create a unique identifier for a slot
const getSlotKey = (slot: SelectedSlot): string => {
    return `${slot.date}-${slot.time}-${slot.type}`;
};

const initialFormDraft: Omit<FormData, 'commencement' | 'completion' | 'preferredTime'> = {
    name: '', prn: '', contact: '', email: '',
    supervisor: SUPERVISORS[0].name,
    supervisorEmail: SUPERVISORS[0].email,
    researcherType: 'BTech',
    workDescription: '', equipment: '',
    hasSpecialConditions: 'No',
    specialConditionTypes: [],
    otherSpecialCondition: '',
    specialInstructions: '',
    consultantClientName: '',
    consultantProjectTitle: '',
    consultantAmountPaid: '',
    consultantTransactionNo: '',
    consultantTransactionDate: '',
};

type ViewState = 'HOME' | 'BOOKING' | 'CONTACT' | 'EXPERIMENTS' | 'RESEARCH' | 'CONSULTANCY' | 'SAFETY' | 'TERMS';

const App: React.FC = () => {
    const [view, setView] = useState<ViewState>('HOME');
    const [formSubmitted, setFormSubmitted] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedSlots, setSelectedSlots] = useState<SelectedSlot[]>([]);
    const [formData, setFormData] = useState<(FormData & { selectedSlots: SelectedSlot[] }) | null>(null);
    const [approvalStatus, setApprovalStatus] = useState<ApprovalStatus>(ApprovalStatus.PENDING_SUPERVISOR);
    const [bookedSlots, setBookedSlots] = useState<Set<string>>(new Set());

    // Form Draft State to preserve typed input
    const [draftFormData, setDraftFormData] = useState<Omit<FormData, 'commencement' | 'completion' | 'preferredTime'>>(initialFormDraft);

    // Safety & Terms Tracking
    const [hasReadSafety, setHasReadSafety] = useState(false);
    const [hasReadTerms, setHasReadTerms] = useState(false);

    // Email Simulation State
    const [sentEmails, setSentEmails] = useState<EmailData[]>([]);

    const addSimulatedEmail = (to: string, subject: string, body: string) => {
        const newEmail: EmailData = {
            id: Math.random().toString(36).substr(2, 9),
            from: 'meera.iitd@gmail.com',
            to,
            subject,
            body,
            timestamp: new Date()
        };
        setSentEmails(prev => [...prev, newEmail]);

        // Auto-remove after 8 seconds
        setTimeout(() => {
            setSentEmails(prev => prev.filter(e => e.id !== newEmail.id));
        }, 8000);
    };

    const handleDismissEmail = (id: string) => {
        setSentEmails(prev => prev.filter(e => e.id !== id));
    };

    const handleStartBooking = () => {
        setView('BOOKING');
        window.scrollTo(0, 0);
    };

    const handleContactClick = () => {
        setView('CONTACT');
        window.scrollTo(0, 0);
    };

    const handleViewExperiments = () => {
        setView('EXPERIMENTS');
        window.scrollTo(0, 0);
    };

    const handleViewResearch = () => {
        setView('RESEARCH');
        window.scrollTo(0, 0);
    };

    const handleViewConsultancy = () => {
        setView('CONSULTANCY');
        window.scrollTo(0, 0);
    };

    const handleViewSafety = () => {
        setHasReadSafety(true);
        setView('SAFETY');
        window.scrollTo(0, 0);
    };

    const handleViewTerms = () => {
        setHasReadTerms(true);
        setView('TERMS');
        window.scrollTo(0, 0);
    };

    const handleReset = useCallback(() => {
        setFormSubmitted(false);
        setFormData(null);
        setSelectedSlots([]);
        setApprovalStatus(ApprovalStatus.PENDING_SUPERVISOR);
        setHasReadSafety(false);
        setHasReadTerms(false);
        setDraftFormData(initialFormDraft);
    }, []);

    const handleBackToHome = useCallback(() => {
        const shouldConfirm = view === 'BOOKING' && !formSubmitted && selectedSlots.length > 0;
        if (shouldConfirm) {
            if (window.confirm("Are you sure you want to go back? Any unsaved progress will be lost.")) {
                handleReset();
                setView('HOME');
                window.scrollTo(0, 0);
            }
        } else {
            // If we are in Safety/Terms, just go back to Booking without resetting
            if (view === 'SAFETY' || view === 'TERMS') {
                setView('BOOKING');
                window.scrollTo(0, 0);
            } else {
                handleReset();
                setView('HOME');
                window.scrollTo(0, 0);
            }
        }
    }, [view, formSubmitted, selectedSlots.length, handleReset]);

    const handleSlotSelect = useCallback((slots: SelectedSlot[]) => {
        setSelectedSlots(slots);
        setTimeout(() => {
             document.getElementById('form-section')?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
    }, []);

    const handleClearSelection = useCallback(() => {
        setSelectedSlots([]);
    }, []);

    const handleSubmit = useCallback((data: Omit<FormData, 'commencement' | 'completion' | 'preferredTime'>) => {
        if (selectedSlots.length === 0) return;

        setIsSubmitting(true);
        setTimeout(() => {
            const fullFormData = { ...data, selectedSlots };
            setFormData(fullFormData);
            setApprovalStatus(ApprovalStatus.PENDING_SUPERVISOR);
            setFormSubmitted(true);
            setIsSubmitting(false);

            setBookedSlots(prev => {
                const newBooked = new Set(prev);
                selectedSlots.forEach(slot => newBooked.add(getSlotKey(slot)));
                return newBooked;
            });

            // Send simulated email to Supervisor
            addSimulatedEmail(
                data.supervisorEmail,
                `Action Required: Lab Approval for ${data.name}`,
                `Dear ${data.supervisor},\n\nStudent ${data.name} (PRN: ${data.prn}) has requested to use the Concrete Technology Lab for ${selectedSlots[0].type} on ${selectedSlots[0].date}. Please log in to approve this request.`
            );

            window.scrollTo(0, 0);
        }, 1000);
    }, [selectedSlots]);

    const handleApprove = useCallback((currentLevel: ApprovalStatus) => {
        if (!formData) return;

        if (currentLevel === ApprovalStatus.PENDING_SUPERVISOR) {
            setApprovalStatus(ApprovalStatus.PENDING_INCHARGE);
            addSimulatedEmail(
                LAB_INCHARGE.email,
                `Action Required: Lab Approval for ${formData.name}`,
                `Dear ${LAB_INCHARGE.name},\n\nSupervisor ${formData.supervisor} has approved the lab utilization request from ${formData.name}. Your final approval is now required.`
            );
        } else if (currentLevel === ApprovalStatus.PENDING_INCHARGE) {
            const isOvernightOrWeekend = formData.selectedSlots.some(slot => 
                slot.type === 'Overnight' || 
                slot.day === 'Saturday' || 
                slot.day === 'Sunday'
            );
            const isConsultancy = formData.researcherType === 'Consultant';

            if (isOvernightOrWeekend || isConsultancy) {
                setApprovalStatus(ApprovalStatus.PENDING_HOD);
                addSimulatedEmail(
                    HOD.email,
                    `Action Required: Program Director Approval for ${formData.name}`,
                    `Dear ${HOD.name},\n\nThis special request (Consultancy/Overnight/Weekend) from ${formData.name} has been approved by the Supervisor and Lab In-charge. Your final sanction is required.`
                );
            } else {
                setApprovalStatus(ApprovalStatus.APPROVED);
                addSimulatedEmail(
                    formData.email,
                    `CONFRIMED: Lab Booking Approved`,
                    `Dear ${formData.name},\n\nYour request for ${formData.selectedSlots[0].type} on ${formData.selectedSlots[0].date} has been fully approved. Please follow all safety protocols.`
                );
            }
        } else if (currentLevel === ApprovalStatus.PENDING_HOD) {
            setApprovalStatus(ApprovalStatus.APPROVED);
            addSimulatedEmail(
                formData.email,
                `CONFRIMED: Lab Booking Approved (Special Request)`,
                `Dear ${formData.name},\n\nYour special request has been sanctioned by the Program Director. Your booking for ${formData.selectedSlots[0].date} is now confirmed.`
            );
        }
    }, [formData]);

    const handleReject = useCallback(() => {
        if (!formData) return;
        setApprovalStatus(ApprovalStatus.REJECTED);
        addSimulatedEmail(
            formData.email,
            `REJECTED: Lab Booking Request`,
            `Dear ${formData.name},\n\nWe regret to inform you that your request for lab utilization has been rejected. Please contact the Lab In-charge for further details.`
        );
    }, [formData]);

    const renderView = () => {
        if (view === 'HOME') {
            return (
              <LandingPage 
                onStartBooking={handleStartBooking} 
                onContactClick={handleContactClick} 
                onViewExperiments={handleViewExperiments}
                onViewResearch={handleViewResearch}
                onViewConsultancy={handleViewConsultancy}
              />
            );
        }

        const backButton = (
            <button 
                onClick={handleBackToHome}
                className="mb-6 flex items-center text-gray-600 hover:text-blue-600 transition-colors group"
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1 group-hover:-translate-x-1 transition-transform" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
                </svg>
                {view === 'SAFETY' || view === 'TERMS' ? 'Back to Form' : 'Back to Home'}
            </button>
        );

        if (view === 'CONTACT') {
            return (
                <div className="animate-fade-in">
                    {backButton}
                    <ContactPage />
                </div>
            );
        }

        if (view === 'EXPERIMENTS') {
            return (
                <div className="animate-fade-in">
                    {backButton}
                    <ExperimentsPage onBookSlot={handleStartBooking} />
                </div>
            );
        }

        if (view === 'RESEARCH') {
            return (
                <div className="animate-fade-in">
                    {backButton}
                    <ResearchPage onBookSlot={handleStartBooking} />
                </div>
            );
        }

        if (view === 'CONSULTANCY') {
            return (
                <div className="animate-fade-in">
                    {backButton}
                    <ConsultancyPage onBookSlot={handleStartBooking} />
                </div>
            );
        }

        if (view === 'SAFETY') {
            return (
                <div className="animate-fade-in">
                    {backButton}
                    <SafetyPage />
                </div>
            );
        }

        if (view === 'TERMS') {
            return (
                <div className="animate-fade-in">
                    {backButton}
                    <TermsPage />
                </div>
            );
        }

        return (
            <div className="animate-fade-in">
                {backButton}

                {formSubmitted && formData ? (
                    <ApprovalStatusDisplay 
                        formData={formData} 
                        status={approvalStatus}
                        onApprove={handleApprove}
                        onReject={handleReject}
                        onReset={handleReset}
                    />
                ) : (
                    <>
                        <CalendarView 
                            onSlotSelect={handleSlotSelect} 
                            selectedSlots={selectedSlots}
                            bookedSlots={bookedSlots}
                        />
                        <div id="form-section">
                            {selectedSlots.length > 0 && (
                                <Form 
                                    onSubmit={handleSubmit} 
                                    isSubmitting={isSubmitting} 
                                    selectedSlots={selectedSlots}
                                    onClearSelection={handleClearSelection}
                                    onViewSafety={handleViewSafety}
                                    onViewTerms={handleViewTerms}
                                    hasReadSafety={hasReadSafety}
                                    hasReadTerms={hasReadTerms}
                                    formData={draftFormData}
                                    setFormData={setDraftFormData}
                                />
                            )}
                        </div>
                    </>
                )}
            </div>
        );
    };

    return (
        <div className="min-h-screen bg-gray-50 font-sans text-gray-900">
            <main className="container mx-auto p-4 md:p-8 max-w-7xl">
                <Header onHomeClick={handleBackToHome} />
                {renderView()}
            </main>
            {/* Email Notification Overlay */}
            <EmailToast emails={sentEmails} onDismiss={handleDismissEmail} />
        </div>
    );
};

export default App;

import React, { useState } from 'react';
import type { FormData, SelectedSlot } from '../types';
import { SUPERVISORS } from '../constants';

interface FormProps {
    onSubmit: (data: Omit<FormData, 'commencement' | 'completion' | 'preferredTime'>) => void;
    isSubmitting: boolean;
    selectedSlots: SelectedSlot[];
    onClearSelection: () => void;
    onViewSafety: () => void;
    onViewTerms: () => void;
    hasReadSafety: boolean;
    hasReadTerms: boolean;
    formData: Omit<FormData, 'commencement' | 'completion' | 'preferredTime'>;
    setFormData: React.Dispatch<React.SetStateAction<Omit<FormData, 'commencement' | 'completion' | 'preferredTime'>>>;
}

const Form: React.FC<FormProps> = ({ 
    onSubmit, 
    isSubmitting, 
    selectedSlots, 
    onClearSelection,
    onViewSafety,
    onViewTerms,
    hasReadSafety,
    hasReadTerms,
    formData,
    setFormData
}) => {
    const [acceptedPolicies, setAcceptedPolicies] = useState(false);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSupervisorChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const selectedSupervisor = SUPERVISORS.find(s => s.name === e.target.value);
        if (selectedSupervisor) {
            setFormData(prev => ({
                ...prev,
                supervisor: selectedSupervisor.name,
                supervisorEmail: selectedSupervisor.email,
            }));
        }
    };

    const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>, field: 'specialConditionTypes') => {
        const { value, checked } = e.target;
        setFormData(prev => {
            const currentValues = prev[field];
            if (checked) {
                return { ...prev, [field]: [...currentValues, value] };
            } else {
                return { ...prev, [field]: currentValues.filter(item => item !== value) };
            }
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!hasReadSafety || !hasReadTerms) {
            alert("Please read both the Safety Instructions and Terms and Conditions before proceeding.");
            return;
        }
        onSubmit(formData);
    };

    const renderInput = (label: string, name: keyof FormData, type: string, required = true, placeholder = '') => (
        <div className="mb-4">
            <label htmlFor={name} className="block text-sm font-medium text-gray-700 mb-1">{label}</label>
            <input 
                type={type} 
                id={name} 
                name={name} 
                value={(formData as any)[name] || ''} 
                onChange={handleChange} 
                required={required} 
                placeholder={placeholder}
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"
            />
        </div>
    );

    // Grouping slots info for display
    const firstSlot = selectedSlots[0];

    const canCheckTerms = hasReadSafety && hasReadTerms;

    return (
        <div className="bg-white p-8 shadow-lg rounded-lg mb-8">
            <h2 className="text-2xl font-bold text-gray-800 mb-2">Step 2: Fill Utilization Details</h2>
            <div className="p-4 bg-gray-100 rounded-lg mb-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <p className="text-sm text-gray-600">You have selected:</p>
                    <p className="font-bold text-blue-800 text-lg">{firstSlot.type} &mdash; {firstSlot.day}, {firstSlot.date}</p>
                    <div className="text-sm font-medium text-gray-700 mt-1">
                        {selectedSlots.map((slot, idx) => (
                            <span key={idx} className="block">• {slot.time}</span>
                        ))}
                    </div>
                </div>
                <button onClick={onClearSelection} className="text-sm bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold py-2 px-4 rounded-lg transition-colors whitespace-nowrap">Change Slots</button>
            </div>

            <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8">
                    {renderInput("1. Name", "name", "text")}
                    {renderInput("2. PRN / Employee No.", "prn", "text")}
                    {renderInput("3. Contact No.", "contact", "tel")}
                    {renderInput("4. Requester E-Mail ID", "email", "email")}
                    <div className="mb-4">
                        <label htmlFor="supervisor" className="block text-sm font-medium text-gray-700 mb-1">5. Name of the supervisor/ PI/ Co-PI</label>
                        <select id="supervisor" name="supervisor" value={formData.supervisor} onChange={handleSupervisorChange} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500">
                            {SUPERVISORS.map(s => <option key={s.email} value={s.name}>{s.name}</option>)}
                        </select>
                    </div>
                </div>

                <div className="mb-4">
                    <h3 className="block text-sm font-medium text-gray-700 mb-1">6. Researcher (Tick any)</h3>
                    <div className="flex flex-wrap gap-4 mt-2">
                        {['BTech', 'MTech', 'PhD', 'JRF-SRF', 'Faculty', 'Consultant'].map(type => (
                            <label key={type} className="flex items-center space-x-2">
                                <input type="radio" name="researcherType" value={type} checked={formData.researcherType === type} onChange={handleChange} className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300"/>
                                <span>{type}</span>
                            </label>
                        ))}
                    </div>
                </div>

                {formData.researcherType === 'Consultant' && (
                    <div className="mb-6 p-5 bg-blue-50 border border-blue-200 rounded-lg animate-fade-in">
                        <h3 className="text-lg font-semibold text-blue-900 mb-3 border-b border-blue-200 pb-2">Consultancy Project Details</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-2">
                            {renderInput("Client Name", "consultantClientName", "text", true)}
                            {renderInput("Title of Project/Work", "consultantProjectTitle", "text", true)}
                            {renderInput("Amount Paid (INR)", "consultantAmountPaid", "number", true)}
                            <div className="grid grid-cols-2 gap-2">
                                {renderInput("Transaction No", "consultantTransactionNo", "text", true)}
                                {renderInput("Date", "consultantTransactionDate", "date", true)}
                            </div>
                        </div>
                        <p className="text-xs text-blue-600 -mt-2 italic">* Please attach payment proofs in email correspondence.</p>
                    </div>
                )}

                <div className="mb-4 border-t pt-4 mt-4">
                    <label htmlFor="workDescription" className="block text-sm font-medium text-gray-700 mb-1">7. Work Description (Not more than 50 words)</label>
                    <textarea id="workDescription" name="workDescription" value={formData.workDescription} onChange={handleChange} required rows={3} maxLength={300} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"></textarea>
                </div>

                <div className="mb-4">
                    <label htmlFor="equipment" className="block text-sm font-medium text-gray-700 mb-1">8. List of equipment, apparatus, and accessories to be used</label>
                    <textarea id="equipment" name="equipment" value={formData.equipment} onChange={handleChange} required rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"></textarea>
                </div>

                <div className="mb-4 border-t pt-4 mt-4">
                    <h3 className="block text-sm font-medium text-gray-700 mb-1">9. Any special conditions during the test?</h3>
                    <div className="flex gap-4 mt-2">
                        <label className="flex items-center space-x-2"><input type="radio" name="hasSpecialConditions" value="No" checked={formData.hasSpecialConditions === 'No'} onChange={handleChange}/><span>No</span></label>
                        <label className="flex items-center space-x-2"><input type="radio" name="hasSpecialConditions" value="Yes" checked={formData.hasSpecialConditions === 'Yes'} onChange={handleChange}/><span>Yes</span></label>
                    </div>
                    {formData.hasSpecialConditions === 'Yes' && (
                        <div className="mt-4 pl-4 border-l-2">
                            <p className="text-sm text-gray-600 mb-2">If yes, please mention:</p>
                             <div className="flex flex-wrap gap-x-4 gap-y-2 text-sm">
                                {['Thermal Variation', 'Acidic', 'Marine', 'Biohazard', 'Radioactive', 'Hazardous'].map(cond => (
                                    <label key={cond} className="flex items-center space-x-2"><input type="checkbox" value={cond} checked={formData.specialConditionTypes.includes(cond)} onChange={(e) => handleCheckboxChange(e, 'specialConditionTypes')} className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300 rounded"/><span>{cond}</span></label>
                                ))}
                            </div>
                            <input type="text" name="otherSpecialCondition" placeholder="Others (please specify)" value={formData.otherSpecialCondition} onChange={handleChange} className="mt-2 w-full md:w-1/2 px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"/>
                        </div>
                    )}
                </div>

                <div className="mb-6">
                    <label htmlFor="specialInstructions" className="block text-sm font-medium text-gray-700 mb-1">10. Any special instructions for Lab assistants or support staff?</label>
                    <textarea id="specialInstructions" name="specialInstructions" value={formData.specialInstructions} onChange={handleChange} rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500"></textarea>
                </div>

                <div className="border-t pt-6">
                    <div className="mb-4 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                        <p className="text-sm text-yellow-800 font-semibold mb-2">Important Documentation Required:</p>
                        <div className="flex flex-col gap-2">
                            <button 
                                type="button" 
                                onClick={onViewSafety}
                                className={`text-left text-sm flex items-center gap-2 ${hasReadSafety ? 'text-green-600 font-bold' : 'text-blue-600 hover:underline'}`}
                            >
                                {hasReadSafety ? '✓' : '→'} Read Safety Instructions
                            </button>
                            <button 
                                type="button" 
                                onClick={onViewTerms}
                                className={`text-left text-sm flex items-center gap-2 ${hasReadTerms ? 'text-green-600 font-bold' : 'text-blue-600 hover:underline'}`}
                            >
                                {hasReadTerms ? '✓' : '→'} Read Terms and Conditions
                            </button>
                        </div>
                        {!canCheckTerms && (
                            <p className="text-[10px] text-yellow-600 mt-2 italic">* You must visit both pages above before you can accept the terms.</p>
                        )}
                    </div>

                    <div className="flex items-start mb-4">
                        <input 
                            id="terms" 
                            type="checkbox" 
                            required 
                            disabled={!canCheckTerms}
                            checked={acceptedPolicies}
                            onChange={(e) => setAcceptedPolicies(e.target.checked)}
                            className={`mt-1 h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded ${!canCheckTerms ? 'cursor-not-allowed opacity-50' : 'cursor-pointer'}`} 
                        />
                        <label htmlFor="terms" className={`ml-2 block text-sm ${!canCheckTerms ? 'text-gray-400' : 'text-gray-900 cursor-pointer'}`}>
                            I accept the Terms and Conditions and safety instructions. I have read and understood the required protocols for lab utilization.
                        </label>
                    </div>

                    <button 
                        type="submit" 
                        disabled={isSubmitting || !acceptedPolicies} 
                        className="w-full bg-blue-600 text-white font-bold py-3 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-gray-400"
                    >
                        {isSubmitting ? 'Submitting...' : 'Submit for Approval'}
                    </button>
                </div>
            </form>
        </div>
    );
};

