import React, { useState, useCallback } from 'react';
import type { FormData, SelectedSlot } from './types';
import { ApprovalStatus } from './types';
import { LAB_INCHARGE, HOD, SUPERVISORS } from './constants';

import Header from './components/Header';
import CalendarView from './components/CalendarView';
import Form from './components/Form';
import ApprovalStatusDisplay from './components/ApprovalStatus';
import LandingPage from './components/LandingPage';
import ContactPage from './components/ContactPage';
import ExperimentsPage from './components/ExperimentsPage';
import ResearchPage from './components/ResearchPage';
import ConsultancyPage from './components/ConsultancyPage';
import SafetyPage from './components/SafetyPage';
import TermsPage from './components/TermsPage';
import EmailToast, { EmailData } from './components/EmailToast';

// Helper to create a unique identifier for a slot
const getSlotKey = (slot: SelectedSlot): string => {
    return `${slot.date}-${slot.time}-${slot.type}`;
};

const initialFormDraft: Omit<FormData, 'commencement' | 'completion' | 'preferredTime'> = {
    name: '', prn: '', contact: '', email: '',
    supervisor: SUPERVISORS[0].name,
    supervisorEmail: SUPERVISORS[0].email,
    researcherType: 'BTech',
    workDescription: '', equipment: '',
    hasSpecialConditions: 'No',
    specialConditionTypes: [],
    otherSpecialCondition: '',
    specialInstructions: '',
    consultantClientName: '',
    consultantProjectTitle: '',
    consultantAmountPaid: '',
    consultantTransactionNo: '',
    consultantTransactionDate: '',
};

type ViewState = 'HOME' | 'BOOKING' | 'CONTACT' | 'EXPERIMENTS' | 'RESEARCH' | 'CONSULTANCY' | 'SAFETY' | 'TERMS';

const App: React.FC = () => {
    const [view, setView] = useState<ViewState>('HOME');
    const [formSubmitted, setFormSubmitted] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedSlots, setSelectedSlots] = useState<SelectedSlot[]>([]);
    const [formData, setFormData] = useState<(FormData & { selectedSlots: SelectedSlot[] }) | null>(null);
    const [approvalStatus, setApprovalStatus] = useState<ApprovalStatus>(ApprovalStatus.PENDING_SUPERVISOR);
    const [bookedSlots, setBookedSlots] = useState<Set<string>>(new Set());

    // Form Draft State to preserve typed input
    const [draftFormData, setDraftFormData] = useState<Omit<FormData, 'commencement' | 'completion' | 'preferredTime'>>(initialFormDraft);

    // Safety & Terms Tracking
    const [hasReadSafety, setHasReadSafety] = useState(false);
    const [hasReadTerms, setHasReadTerms] = useState(false);

    // Email Simulation State
    const [sentEmails, setSentEmails] = useState<EmailData[]>([]);

    const handleDismissEmail = (id: string) => {
        setSentEmails(prev => prev.filter(e => e.id !== id));
    };

    const handleApprove = useCallback((currentLevel: ApprovalStatus) => {
        setApprovalStatus(prevStatus => {
            // Because setApprovalStatus functional update might be tricky with emails, 
            // we use a side-effect approach or just rely on the existing closure if possible.
            // But handleApprove is already a stable callback.
            return prevStatus; 
        });

        // Actual implementation logic moved into a helper to be callable from both UI and Email
        performApproval(currentLevel);
    }, [formData]);

    const handleReject = useCallback(() => {
        if (!formData) return;
        setApprovalStatus(ApprovalStatus.REJECTED);
        addSimulatedEmail(
            formData.email,
            `REJECTED: Lab Booking Request`,
            `Dear ${formData.name},\n\nWe regret to inform you that your request for lab utilization has been rejected. Please contact the Lab In-charge for further details.`
        );
    }, [formData]);

    const performApproval = (currentLevel: ApprovalStatus) => {
        if (!formData) return;

        if (currentLevel === ApprovalStatus.PENDING_SUPERVISOR) {
            setApprovalStatus(ApprovalStatus.PENDING_INCHARGE);
            addSimulatedEmail(
                LAB_INCHARGE.email,
                `Action Required: Lab Approval for ${formData.name}`,
                `Dear ${LAB_INCHARGE.name},\n\nSupervisor ${formData.supervisor} has approved the lab utilization request from ${formData.name}. Your final approval is now required.`,
                {
                    onApprove: () => performApproval(ApprovalStatus.PENDING_INCHARGE),
                    onReject: handleReject,
                    label: 'Lab In-charge'
                }
            );
        } else if (currentLevel === ApprovalStatus.PENDING_INCHARGE) {
            const isOvernightOrWeekend = formData.selectedSlots.some(slot => 
                slot.type === 'Overnight' || 
                slot.day === 'Saturday' || 
                slot.day === 'Sunday'
            );
            const isConsultancy = formData.researcherType === 'Consultant';

            if (isOvernightOrWeekend || isConsultancy) {
                setApprovalStatus(ApprovalStatus.PENDING_HOD);
                addSimulatedEmail(
                    HOD.email,
                    `Action Required: Program Director Approval for ${formData.name}`,
                    `Dear ${HOD.name},\n\nThis special request (Consultancy/Overnight/Weekend) from ${formData.name} has been approved by the Supervisor and Lab In-charge. Your final sanction is required.`,
                    {
                        onApprove: () => performApproval(ApprovalStatus.PENDING_HOD),
                        onReject: handleReject,
                        label: 'Program Director'
                    }
                );
            } else {
                setApprovalStatus(ApprovalStatus.APPROVED);
                addSimulatedEmail(
                    formData.email,
                    `CONFRIMED: Lab Booking Approved`,
                    `Dear ${formData.name},\n\nYour request for ${formData.selectedSlots[0].type} on ${formData.selectedSlots[0].date} has been fully approved. Please follow all safety protocols.`
                );
            }
        } else if (currentLevel === ApprovalStatus.PENDING_HOD) {
            setApprovalStatus(ApprovalStatus.APPROVED);
            addSimulatedEmail(
                formData.email,
                `CONFRIMED: Lab Booking Approved (Special Request)`,
                `Dear ${formData.name},\n\nYour special request has been sanctioned by the Program Director. Your booking for ${formData.selectedSlots[0].date} is now confirmed.`
            );
        }
    };

    const addSimulatedEmail = (to: string, subject: string, body: string, actions?: EmailData['actions']) => {
        const newEmail: EmailData = {
            id: Math.random().toString(36).substr(2, 9),
            from: 'ctl@mitwpu.edu.in',
            to,
            subject,
            body,
            timestamp: new Date(),
            actions
        };
        setSentEmails(prev => [...prev, newEmail]);

        // Auto-remove after 15 seconds if it has actions, 8 seconds otherwise
        const timeout = actions ? 15000 : 8000;
        setTimeout(() => {
            setSentEmails(prev => prev.filter(e => e.id !== newEmail.id));
        }, timeout);
    };

    const handleStartBooking = () => {
        setView('BOOKING');
        window.scrollTo(0, 0);
    };

    const handleContactClick = () => {
        setView('CONTACT');
        window.scrollTo(0, 0);
    };

    const handleViewExperiments = () => {
        setView('EXPERIMENTS');
        window.scrollTo(0, 0);
    };

    const handleViewResearch = () => {
        setView('RESEARCH');
        window.scrollTo(0, 0);
    };

    const handleViewConsultancy = () => {
        setView('CONSULTANCY');
        window.scrollTo(0, 0);
    };

    const handleViewSafety = () => {
        setHasReadSafety(true);
        setView('SAFETY');
        window.scrollTo(0, 0);
    };

    const handleViewTerms = () => {
        setHasReadTerms(true);
        setView('TERMS');
        window.scrollTo(0, 0);
    };

    const handleReset = useCallback(() => {
        setFormSubmitted(false);
        setFormData(null);
        setSelectedSlots([]);
        setApprovalStatus(ApprovalStatus.PENDING_SUPERVISOR);
        setHasReadSafety(false);
        setHasReadTerms(false);
        setDraftFormData(initialFormDraft);
    }, []);

    const handleBackToHome = useCallback(() => {
        const shouldConfirm = view === 'BOOKING' && !formSubmitted && selectedSlots.length > 0;
        if (shouldConfirm) {
            if (window.confirm("Are you sure you want to go back? Any unsaved progress will be lost.")) {
                handleReset();
                setView('HOME');
                window.scrollTo(0, 0);
            }
        } else {
            // If we are in Safety/Terms, just go back to Booking without resetting
            if (view === 'SAFETY' || view === 'TERMS') {
                setView('BOOKING');
                window.scrollTo(0, 0);
            } else {
                handleReset();
                setView('HOME');
                window.scrollTo(0, 0);
            }
        }
    }, [view, formSubmitted, selectedSlots.length, handleReset]);

    const handleSlotSelect = useCallback((slots: SelectedSlot[]) => {
        setSelectedSlots(slots);
        setTimeout(() => {
             document.getElementById('form-section')?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
    }, []);

    const handleClearSelection = useCallback(() => {
        setSelectedSlots([]);
