const Header: React.FC<HeaderProps> = ({ onHomeClick }) => {
  return (
    <div 
        className={`bg-white p-6 md:p-10 shadow-sm rounded-3xl mb-8 border border-gray-100 text-center relative group ${onHomeClick ? 'cursor-pointer hover:shadow-md transition-shadow' : ''}`}
        onClick={onHomeClick}
